begin;
update public.content_documents set categoria='ferramenta',subtipo=null,payload=(payload || '{"categoria":"ferramenta","categoria_label":"Ferramentas","subtipo":null,"descricao_curta":"Comum","descricao_longa":"*Comum*\nAs Luvas de Escalada possuem palmas aderentes, reforços nos dedos e pequenas garras retráteis para encontrar apoio em concreto, pedra, estruturas metálicas e outras superfícies irregulares. São usadas em manutenção vertical, resgate e acesso a estruturas onde uma rota convencional não está disponível.\n**Escalada:** você recebe **+1 de vantagem** em testes de **`Mobilidade`** realizados para escalar.\nEnquanto escala uma superfície que ofereça apoios suficientes, você pode usar **Manobrar** normalmente para se deslocar por ela.\nAs luvas não permitem escalar superfícies completamente lisas ou sem pontos de apoio adequados. Durante a escalada, suas mãos ficam ocupadas.\n**Espaços:** 1\n**Preço:** 120 Ⱥ","dados_notion":{"pagina":"FERRAMENTAS E UTILIDADES","campos":{"Item":"Luvas de Escalada","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"}},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-11T07:09:46.548Z"},"updated_at":"2026-10-11"}'::jsonb), updated_at=now(), payload_hash=payload_hash where id='item:mobilidade_luvas_de_escalada';
insert into public.content_documents (id,content_type,slug,nome,categoria,status,version,source_pack_id,source_pack_version,payload,payload_hash,published_at) values ('item:ferramentas_mochila_mk_i','item','ferramentas_mochila_mk_i','Mochila MK-I','ferramenta','published','1.2.0','ruptura-notion-v12','1.2.0','{"id":"ferramentas_mochila_mk_i","slug":"ferramentas_mochila_mk_i","nome":"Mochila MK-I","categoria":"ferramenta","categoria_label":"Ferramentas","raridade":"comum","preco":200,"preco_texto":"200","estatisticas":{"espacos_texto":"2 (vazia, quando não equipada)","capacidade_mochila":10},"descricao_longa":"*Comum*\nMochila tecnomágica de uso cotidiano, equipada com runas simples de Material e Cinética que auxiliam a compactação e a compensação da carga transportada. Todo personagem recebe uma Mochila MK-I na criação.\n**Capacidade:** 10 espaços.\n**Equipamento:** ocupa a posição Mochila de Equipado e não utiliza espaços de armazenamento enquanto equipada. Apenas uma Mochila MK pode permanecer equipada por vez.\n**Armazenamento:** segue as regras de Mochila e Armazenamento Tecnomágico do capítulo Inventário. Não pode ser guardada dentro de outra Mochila MK enquanto contiver itens.\n**Espaços:** 2 (vazia, quando não equipada).\n**Preço:** 200 Ⱥ","descricao_curta":"Mochila tecnomágica de uso cotidiano, equipada com runas simples de Material e Cinética que auxiliam a compactação e a compensação da carga transportada. Todo personagem recebe uma Mochila MK-I na criação.","status":"published","versao":"1.2.0","uso_manual":true,"tags":["loja"],"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-11T07:09:46.548Z"},"dados_notion":{"pagina":"FERRAMENTAS E UTILIDADES"},"payload_automacao":{"efeitos":[]}}'::jsonb,'f70762e7467cdcc495978c24582097dfecc8f661276672a484a271edf4043b08',now()) on conflict(id) do update set payload=excluded.payload,payload_hash=excluded.payload_hash,nome=excluded.nome,categoria=excluded.categoria,status=excluded.status,updated_at=now();
insert into public.content_documents (id,content_type,slug,nome,categoria,status,version,source_pack_id,source_pack_version,payload,payload_hash,published_at) values ('item:ferramentas_mochila_mk_ii','item','ferramentas_mochila_mk_ii','Mochila MK-II','ferramenta','published','1.2.0','ruptura-notion-v12','1.2.0','{"id":"ferramentas_mochila_mk_ii","slug":"ferramentas_mochila_mk_ii","nome":"Mochila MK-II","categoria":"ferramenta","categoria_label":"Ferramentas","raridade":"incomum","preco":600,"preco_texto":"600","estatisticas":{"espacos_texto":"2 (vazia, quando não equipada)","capacidade_mochila":15},"descricao_longa":"*Incomum*\nMochila tecnomágica com uma matriz rúnica compacta que reduz temporariamente o volume dos objetos armazenados, reorganiza sua acomodação e compensa melhor a carga transportada.\n**Capacidade:** 15 espaços.\n**Equipamento:** ocupa a posição Mochila de Equipado e não utiliza espaços de armazenamento enquanto equipada. Apenas uma Mochila MK pode permanecer equipada por vez.\n**Armazenamento:** segue as regras de Mochila e Armazenamento Tecnomágico do capítulo Inventário. Não pode ser guardada dentro de outra Mochila MK enquanto contiver itens.\n**Espaços:** 2 (vazia, quando não equipada).\n**Preço:** 600 Ⱥ","descricao_curta":"Mochila tecnomágica com uma matriz rúnica compacta que reduz temporariamente o volume dos objetos armazenados, reorganiza sua acomodação e compensa melhor a carga transportada.","status":"published","versao":"1.2.0","uso_manual":true,"tags":["loja"],"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-11T07:09:46.548Z"},"dados_notion":{"pagina":"FERRAMENTAS E UTILIDADES"},"payload_automacao":{"efeitos":[]}}'::jsonb,'8ac4a66b7cbb1ff594376ba197a94dfc64f062dedf59645c18dc91e2a46262e1',now()) on conflict(id) do update set payload=excluded.payload,payload_hash=excluded.payload_hash,nome=excluded.nome,categoria=excluded.categoria,status=excluded.status,updated_at=now();
insert into public.content_documents (id,content_type,slug,nome,categoria,status,version,source_pack_id,source_pack_version,payload,payload_hash,published_at) values ('item:ferramentas_mochila_mk_iii','item','ferramentas_mochila_mk_iii','Mochila MK-III','ferramenta','published','1.2.0','ruptura-notion-v12','1.2.0','{"id":"ferramentas_mochila_mk_iii","slug":"ferramentas_mochila_mk_iii","nome":"Mochila MK-III","categoria":"ferramenta","categoria_label":"Ferramentas","raridade":"raro","preco":1500,"preco_texto":"1500","estatisticas":{"espacos_texto":"2 (vazia, quando não equipada)","capacidade_mochila":20},"descricao_longa":"*Raro*\nMochila tecnomágica com uma malha rúnica avançada que maximiza a compactação e reduz drasticamente o esforço necessário para transportar seu conteúdo.\n**Capacidade:** 20 espaços.\n**Equipamento:** ocupa a posição Mochila de Equipado e não utiliza espaços de armazenamento enquanto equipada. Apenas uma Mochila MK pode permanecer equipada por vez.\n**Armazenamento:** segue as regras de Mochila e Armazenamento Tecnomágico do capítulo Inventário. Não pode ser guardada dentro de outra Mochila MK enquanto contiver itens.\n**Espaços:** 2 (vazia, quando não equipada).\n**Preço:** 1.500 Ⱥ","descricao_curta":"Mochila tecnomágica com uma malha rúnica avançada que maximiza a compactação e reduz drasticamente o esforço necessário para transportar seu conteúdo.","status":"published","versao":"1.2.0","uso_manual":true,"tags":["loja"],"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-11T07:09:46.548Z"},"dados_notion":{"pagina":"FERRAMENTAS E UTILIDADES"},"payload_automacao":{"efeitos":[]}}'::jsonb,'961cb35fa38d01242fec6248799071e0f5562eb82e2d2e068589099d7688b49b',now()) on conflict(id) do update set payload=excluded.payload,payload_hash=excluded.payload_hash,nome=excluded.nome,categoria=excluded.categoria,status=excluded.status,updated_at=now();

update public.content_documents set payload_hash=encode(sha256(convert_to(payload::text,'UTF8')),'hex') where slug in ('mobilidade_luvas_de_escalada','ferramentas_mochila_mk_i','ferramentas_mochila_mk_ii','ferramentas_mochila_mk_iii');

update public.content_documents set payload=jsonb_set(payload,'{estatisticas}',(payload->'estatisticas')-'posicao_mobilidade' || jsonb_build_object('campos_tabela',(payload->'estatisticas'->'campos_tabela')-'Tipo')) where slug='mobilidade_luvas_de_escalada';
update public.content_documents set payload_hash=encode(sha256(convert_to(payload::text,'UTF8')),'hex') where slug='mobilidade_luvas_de_escalada';

-- Preserve every instance and its slug; obsolete glove positions become stored tools.
update public.characters c set payload=jsonb_set(c.payload,'{inventario}', (
 select coalesce(jsonb_agg(
 case when i->>'itemSlug'='mobilidade_luvas_de_escalada' then
 (case when i->>'encaixeEscolhido'='luvas' then (i-'encaixeEscolhido') || '{"estado":"mochila"}'::jsonb else i end) || '{"categoria":"ferramenta"}'::jsonb
 when i->>'encaixeEscolhido'='luvas' then (i-'encaixeEscolhido') || '{"estado":"mochila"}'::jsonb else i end order by ord),'[]'::jsonb)
 from jsonb_array_elements(coalesce(c.payload->'inventario','[]')) with ordinality a(i,ord)
)),updated_at=now()
where exists(select 1 from jsonb_array_elements(coalesce(c.payload->'inventario','[]')) i where i->>'itemSlug'='mobilidade_luvas_de_escalada' or i->>'encaixeEscolhido'='luvas');

-- Materialize the formerly implicit basic backpack exactly once.
update public.characters c set payload=jsonb_set(c.payload,'{inventario}', coalesce(c.payload->'inventario','[]') || jsonb_build_array(jsonb_build_object(
'id',gen_random_uuid()::text,'itemSlug','ferramentas_mochila_mk_i','itemNome','Mochila MK-I','categoria','ferramenta','quantidade',1,'estado','equipado','encaixeEscolhido','mochila_equipada','precoPago',0,'adquiridoEm',now()::text))),updated_at=now()
where not exists(select 1 from jsonb_array_elements(coalesce(c.payload->'inventario','[]')) i where i->>'itemSlug' in ('ferramentas_mochila_mk_i','ferramentas_mochila_mk_ii','ferramentas_mochila_mk_iii') or i->>'itemNome' ~* '^Mochila MK-(I|II|III)$');

-- Existing creation authorization and validations are retained. Only one MK-I is free.
do $migration$
declare definition text; needle text := 'v_preco := coalesce((v_item_payload->>''preco'')::numeric, 0) * v_quantidade;';
begin
 select pg_get_functiondef(oid) into definition from pg_proc where oid='public.complete_character_creation_v2(uuid,jsonb,text,text,uuid)'::regprocedure;
 if position('v_mochila_gratis' in definition)=0 then
  if position(needle in definition)=0 then raise exception 'Creation function changed; inspect before updating'; end if;
  definition:=replace(definition,'v_gasto numeric := 0;','v_gasto numeric := 0; v_mochila_gratis boolean := false;');
  definition:=replace(definition,needle,needle || E'\n    if v_item->>''itemSlug''=''ferramentas_mochila_mk_i'' and (v_item->>''precoPago'')::numeric=0 then\n      if v_mochila_gratis or v_quantidade<>1 then raise exception ''Only one initial MK-I is free''; end if;\n      v_mochila_gratis:=true; v_preco:=0;\n    end if;');
  definition:=replace(definition,'if v_gasto > v_aretz then', 'if not v_mochila_gratis then raise exception ''Initial MK-I is required''; end if; if v_gasto > v_aretz then');
  execute definition;
 end if;
end $migration$;

-- Enforce independent backpack exclusivity on all character write paths.
create or replace function public.validate_backpack_equipment() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $fn$
declare n integer;
begin
 if exists(select 1 from jsonb_array_elements(coalesce(new.payload->'inventario','[]')) i where i->>'encaixeEscolhido'='luvas') then
  raise exception 'The Luvas equipment position was removed';
 end if;
 select count(*) into n from jsonb_array_elements(coalesce(new.payload->'inventario','[]')) i
 where i->>'estado'='equipado' and (i->>'encaixeEscolhido'='mochila_equipada' or i->>'itemSlug' in ('ferramentas_mochila_mk_i','ferramentas_mochila_mk_ii','ferramentas_mochila_mk_iii'));
 if n>1 then raise exception 'Only one Mochila MK can be equipped'; end if;
 if exists(select 1 from jsonb_array_elements(coalesce(new.payload->'inventario','[]')) i where i->>'estado'='equipado' and i->>'encaixeEscolhido'='mochila_equipada' and (i->>'quantidade')::numeric<>1) then
  raise exception 'Equip one backpack instance at a time';
 end if;
 return new;
end $fn$;
drop trigger if exists validate_backpack_equipment on public.characters;
create trigger validate_backpack_equipment before insert or update of payload on public.characters for each row execute function public.validate_backpack_equipment();
commit;
